#define GFS_CURVED_TARGET_INTEGRAL_LIBRARY
#include "test_curved_target_integral_v1.cpp"
#include "material_target_gluing.h"
namespace ta=material_target_analytic;namespace gl=material_target_gluing;
struct ReferencePiece {std::array<S,2> vertex[3];};
static std::array<Q,12> remainder(const curved::Packet&p,const curved::Record&r,const ReferencePiece&piece,bool&pass,const char*&reason){
    const Q R=Q(.875L),h=Q(.5L)+R;S D[2][2];Q anchor[2],radius[2];for(int k=0;k<2;k++){D[0][k]=piece.vertex[1][k]-piece.vertex[0][k];D[1][k]=piece.vertex[2][k]-piece.vertex[0][k];S center=piece.vertex[0][k]+S(Q(.5L))*D[0][k]+S(Q(.25L))*D[1][k];anchor[k]=center.n;Q a=ti::mag(D[0][k]-S(Q(.5L))*D[1][k]),b=ti::mag(D[1][k]);Q u=ti::add(ti::mul(h,a),ti::mul(ti::add(Q(.25L),ti::mul(h,Q(.5L))),b)),v=ti::add(ti::mul(Q(.5L),a),ti::mul(h,b));radius[k]=ti::add(center.e,std::max(u,v));}
    auto map=tg::compile(r,anchor,p.parameters[3]);auto field=ta::bounds(map,p,radius);std::array<Q,12> error={};if(!field.pass){pass=false;reason=field.reason;return error;}S jac=td::cross(D[0],D[1]);need(ti::lower(jac)>0,"positive reference subdivision");S f16(1),f32(1);for(int k=2;k<=32;k++){f32=f32*S(k);if(k<=16)f16=f16*S(k);}S ratio=f16*f16/f32,C=ratio*ratio/S(33)*mf::power(S(R),Q(-32));Q coefficient=ti::mul(Q(2),ti::mag(C));for(int k=0;k<12;k++)error[k]=ti::mul(coefficient,ti::mul(ti::mul(Q(1)+R,ti::mag(jac)),ti::mul(field.moment[k],field.Jhi)));return error;
}
int main(int argc,char**argv){int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);active_mpi=true;need(argc==6,"original packet sites guard NEW output 225|137");size_t it=atoi(argv[5]);need(it==225||it==137,"same two physical controls");auto p=curved::read(argv[1]);auto sites=curved_partition::read_sites(argv[2]);auto weights=read_weights(argv[3],sites);std::string dest=argv[4];const auto&r=p.record[it];auto started=std::chrono::steady_clock::now();std::array<S,2> original[3],mid[3];for(int a=0;a<3;a++)for(int k=0;k<2;k++)original[a][k]=S(Q(r.triangle.geometry.x[a][k]));for(int a=0;a<3;a++)for(int k=0;k<2;k++)mid[a][k]=(original[a][k]+original[(a+1)%3][k])/S(2);
    std::vector<ReferencePiece> pieces={{{original[0],mid[0],mid[2]}},{{original[1],mid[1],mid[0]}},{{original[2],mid[2],mid[1]}},{{mid[0],mid[1],mid[2]}}};auto gauss=ti::gauss16();mf::B<R> total[NMOMENT];S reference[NMOMENT];Q quad_error[NMOMENT]={};uint64_t oracle_excess=0,points=0,failed_remainders=0;std::ofstream proof(dest+"/source_baseline_piece_bounds.csv"),pointledger(dest+"/source_baseline_positive_points.csv");proof<<"piece,pass,reason,K_remainder,U_remainder,potential_remainder,Udot_remainder\n";pointledger<<"point,piece,X,Y,positive_reference_weight\n";
    for(size_t ip=0;ip<pieces.size();ip++){const auto&piece=pieces[ip];bool pass=true;const char*reason="pass";auto error=remainder(p,r,piece,pass,reason);proof<<ip<<','<<pass<<','<<reason;for(int k:{KINETIC,THERMAL,POTENTIAL,THERMAL_RATE})proof<<','<<(pass?qs(error[k]):"unproved");proof<<'\n';failed_remainders+=!pass;if(pass)for(int k=0;k<NMOMENT;k++)quad_error[k]=ti::add(quad_error[k],error[k]);Q anchor[2];for(int k=0;k<2;k++){S center;for(int a=0;a<3;a++)center=center+piece.vertex[a][k]/S(3);anchor[k]=center.n;}auto map=tg::compile(r,anchor,p.parameters[3]);S D[2][2];for(int k=0;k<2;k++){D[0][k]=piece.vertex[1][k]-piece.vertex[0][k];D[1][k]=piece.vertex[2][k]-piece.vertex[0][k];}S jac=td::cross(D[0],D[1]);for(int iu=0;iu<16;iu++)for(int iv=0;iv<16;iv++){S u=gauss.x[iu],v=gauss.x[iv],X=piece.vertex[0][0]+u*D[0][0]+(S(1)-u)*v*D[1][0],Y=piece.vertex[0][1]+u*D[0][1]+(S(1)-u)*v*D[1][1],w=jac*(S(1)-u)*gauss.w[iu]*gauss.w[iv];need(ti::lower(w)>0,"positive reference source baseline");auto native=tg::evaluate<R>(map,X,Y);auto oracle=mf::original_at(r,X,Y,p.parameters[3]);auto nr=profile(p,ti::cast(X),ti::cast(Y),true);auto qr=profile(p,X,Y,false);auto nn=physical_moment(p,native,nr,native.position[0],native.position[1],ti::cast(w)*native.J);auto oo=physical_moment(p,oracle,qr,oracle.position[0],oracle.position[1],w*oracle.J);for(int k=0;k<NMOMENT;k++){if(fabsq(Q(nn[k].n)-oo[k].n)>mf::FP<Q>::up(Q(nn[k].e)+oo[k].e))oracle_excess++;total[k]=total[k]+nn[k];reference[k]=reference[k]+oo[k];}pointledger<<points++<<','<<ip<<','<<qs(X.n)<<','<<qs(Y.n)<<','<<qs(w.n)<<'\n';}}
    proof.close();pointledger.close();need(oracle_excess==0,"same original source baseline moment model");std::ofstream source(dest+"/source_baseline_moments.csv");source<<std::setprecision(21)<<"source,moment,native,original_basis_same_rule,field_geometry_node_sum_bound,analytic_remainder_complete,analytic_remainder,total_error_bound\n";for(int k=0;k<NMOMENT;k++){R qe=nextafterl(R(quad_error[k]),INFINITY);source<<r.cell<<','<<moment_names[k]<<','<<total[k].n<<','<<qs(reference[k].n)<<','<<total[k].e<<','<<(!failed_remainders)<<','<<(failed_remainders?"unproved":qs(quad_error[k]))<<','<<(failed_remainders?"unproved":qs(Q(mf::plus_up(total[k].e,qe))))<<'\n';}source.close();auto glue=gl::audit(p,it,sites,weights,dest);std::ofstream errors(dest+"/target_gluing_bounds.csv");errors<<"target,moment,all_touched_edges_complete,domain_and_field_ambiguity_bound\n";for(size_t j=0;j<sites.size();j++)for(int k=0;k<NMOMENT;k++)errors<<sites[j].id<<','<<moment_names[k]<<','<<glue.pass<<','<<(glue.pass?qs(glue.error[j][k]):"unproved")<<'\n';errors.close();bool complete=!failed_remainders&&glue.pass;
    printf("{\"scope\":\"same original physical source reference baseline with fixed4 positive subtriangles and Gauss16/Cauchy radius7/8; all3 touched shared traces with16 fixed parts, ruled-strip ambiguity and both source field envelopes; no trace averaging or owner assignment\",\"triangle\":%zu,\"source_baseline_points\":%llu,\"oracle_excess\":%llu,\"failed_baseline_remainders\":%llu,\"paired_touched_edges\":%llu,\"shared_parts\":%llu,\"possible_target_strip_parts\":%llu,\"max_original_position_trace_gap\":%.17Lg,\"max_original_velocity_trace_gap\":%.17Lg,\"gluing_complete\":%s,\"gluing_reason\":\"%s\",\"source_and_gluing_complete\":%s,\"exact_global_C0_proved\":false,\"full_target_assembly_complete\":false,\"full_cold_transfer_proved\":false,\"seconds\":%.17g}\n",it,(unsigned long long)points,(unsigned long long)oracle_excess,(unsigned long long)failed_remainders,(unsigned long long)glue.paired,(unsigned long long)glue.parts,(unsigned long long)glue.possible_target_parts,R(glue.max_position),R(glue.max_velocity),glue.pass?"true":"false",glue.reason,complete?"true":"false",std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count());active_mpi=false;MPI_Finalize();return complete?0:2;
}
